fn shell_game(n: i32, x: i8) -> i8 {
    debug_assert!(n >= 1);
    debug_assert!((0..=2).contains(&x));

    // The game repeats every 6 moves (composition of swaps has period 6).
    // Reduce n to r in 0..=5.
    let r = ((n % 6) + 6) % 6; // robust even if n were negative

    match r {
        0 => x,
        1 => match x { 0 => 1, 1 => 0, _ => 2 },
        2 => match x { 0 => 1, 1 => 2, _ => 0 },
        3 => match x { 0 => 2, 1 => 1, _ => 0 },
        4 => match x { 0 => 2, 1 => 0, _ => 1 },
        5 => match x { 0 => 0, 1 => 2, _ => 1 },
        _ => unreachable!(),
    }
}